Definition sels_static (C : lctx) (A : AS) (sh : bool) (sel1 sel2 : Z) (sv1 sv2 : selv) : Prop :=
  v_name sv1 = 0%Z /\ v_name sv2 = 0%Z /\ csels_shape (ssz sh) (sdir sh) sv1 sv2 /\
  (forall q, sblk sel1 sv1 q \/ sblk sel2 sv2 q -> live A q = None /\ live (c_A0 C) q = None) /\
  (forall q, sblk sel1 sv1 q -> ~ sblk sel2 sv2 q).

