Lemma csc_seld4 : forall (sh : bool) (fr : bvmap 5 word) C Ar A m md regs (s pix1 w h cm datas : Z) (cv : cmapv) (ret : word) (S : TSet) (kR bR : Z)
    (fr1 : bvmap 5 word) (cs1 : bv 32) (A0 : AS) (m0 : word -> option byte) (vm0 : VmMaps) (r0 : bvmap 5 word) (cm' : Z) (cv' : cmapv) (kx bx : Z)
    (sel1 sel2 : Z) (sv1 sv2 : selv),
  Cok C -> (s mod 16 = 0)%Z -> (c_top C - LSTK + CSC_STACK <= s)%Z -> (s <= c_top C)%Z -> ret_ok ret ->
  getr regs 2 = Z_to_bv 64 s -> getr regs 4 = Z_to_bv 64 0x123d20 -> sub_live Ar A ->
  frm_zero cs1 -> (forall r : reg, In (u r) fs_list -> reg_get fr1 r = reg_get fr r) ->
  W C A0 m0 (with_vmmaps vm0 md) ->
  getr r0 2 = Z_to_bv 64 (s - 112) -> getr r0 8 = Z_to_bv 64 pix1 -> rkept regs r0 ->
  FRS m0 s ret regs ->
  rdn SEGS m0 (Z_to_bv 64 (co1 sh s)) 8 = Some (Z_to_le_bytes 8 sel1) -> rdn SEGS m0 (Z_to_bv 64 (co2 sh s)) 8 = Some (Z_to_le_bytes 8 sel2) ->
  rdn SEGS m0 (Z_to_bv 64 (cz1 sh s)) 8 = Some (Z_to_le_bytes 8 0) -> rdn SEGS m0 (Z_to_bv 64 (cz2 sh s)) 8 = Some (Z_to_le_bytes 8 0) ->
  sub_live Ar A0 -> POSTM C Ar s m m0 ->
  pix1_at C Ar A0 m0 pix1 w h cm' datas cv' ->
  sel_at (alloc_top (c_vm C)) A0 m0 sel1 sv1 -> sel_at (alloc_top (c_vm C)) A0 m0 sel2 sv2 -> sels_static C A sh sel1 sel2 sv1 sv2 ->
  (forall q, sblk sel1 sv1 q \/ sblk sel2 sv2 q -> ~ tblk pix1 datas cm' cv' q) ->
  cslm (fun q => sblk sel1 sv1 q \/ sblk sel2 sv2 q) A A0 cm cv cm' cv' ->
  aroom A0 vm0 kx bx -> (kR - RK_csc (vsz sh) <= kx)%Z -> (bR - RB_csc (vsz sh) w h cm <= bx)%Z ->
  (0 <= kR - RK_csc (vsz sh))%Z -> (0 <= bR - RB_csc (vsz sh) w h cm)%Z ->
  csc_K fr C Ar A m md regs s pix1 (vsz sh) w h cm datas cv ret S kR bR ->
  realizes SEGS (mkCfg (@mkst (mkFP fr1 cs1) r0 (0x923a4 : word) m0 al_rom) (with_vmmaps vm0 md)) S.
Proof.
